+
+function handleDragOver(e: DragEvent) {
+	e.preventDefault();
+	e.stopPropagation();
+}
+
+function handleDragEnter(e: DragEvent) {
+	e.preventDefault();
+	e.stopPropagation();
+	dragCounter++;
+}
+
+function handleDragLeave(e: DragEvent) {
+	e.preventDefault();
+	e.stopPropagation();
+	dragCounter--;
