body:
The hardcoded limit of 100 projects could cause issues if repositories have more than 100 projects. Consider implementing pagination or making this configurable.
```suggestion

	query := `
		query($owner: String!, $repo: String!, $after: String) {
			repository(owner: $owner, name: $repo) {
				projects(first: 100, states: OPEN, after: $after) {
					nodes {
						id
						name
					}
					pageInfo {
						hasNextPage
						endCursor
					}
				}
			}
		}`

	var after *string
	for {
		variables := map[string]interface{}{
			"owner": owner,
			"repo":  repo,
			"after": after,
		}

		var response struct {
			Repository struct {
				Projects struct {
					Nodes []struct {
						ID   string `json:"id"`
						Name string `json:"name"`
					} `json:"nodes"`
					PageInfo struct {
						HasNextPage bool   `json:"hasNextPage"`
						EndCursor   string `json:"endCursor"`
					} `json:"pageInfo"`
				} `json:"projects"`
			} `json:"repository"`
		}

		err := client.Do(query, variables, &response)
		if err != nil {
			return "", fmt.Errorf("failed to get projects: %w", err)
		}

		for _, p := range response.Repository.Projects.Nodes {
			if strings.EqualFold(p.Name, project) {
				return p.ID, nil
			}
		}

		if response.Repository.Projects.PageInfo.HasNextPage {
			after = &response.Repository.Projects.PageInfo.EndCursor
		} else {
			break
		}
	}
```

